#!/usr/bin/env python3
from ta_emss import ta_emss


if __name__ == "__main__":

    ################################################################################
    # Create EMSS instance and setup BTS OAM for 128 X2AP links (default is 64)
    ################################################################################
    emss1 = ta_emss()
    emss1.setup_emss(bts_id=1)
    emss1.configure_bts([{'MOC': 'ANR', 'ID': 0, 'maxNumX2LinksIn': 128}])

    ################################################################################
    # Configure Xterminator with 128 eNBs and IP addresses
    ################################################################################
    print("Setting xterminator up...")
    emss1.xterm_setup(
        # BTS section
        bts_ip_addr="10.0.1.2",
        # ENBsim local IP section
        enbsim_ip_addr_begin="10.0.201.1",
        enbsim_ip_addr_end="10.0.201.128",
        enbsim_ip_addr_mask=24,
        enbsim_eth_if="eth3",
        # ENBsim configuration
        init_enb_pci_max=503,
        init_enb_enb_id=4001,
        init_enb_mcc="440",
        init_enb_mnc="08",
        init_enb_tac=1,
        init_enb_dl_earfcn=4900,
        init_enb_dl_bandwidth=10,
        init_enb_gu_group_id_list=[
            {"MCC": "244", "MNC": "08", "MME_GROUP_ID": 12},
            {"MCC": "244", "MNC": "08", "MME_GROUP_ID": 13},
            {"MCC": "244", "MNC": "08", "MME_GROUP_ID": 14},
            {"MCC": "244", "MNC": "08", "MME_GROUP_ID": 15},
            {"MCC": "244", "MNC": "08", "MME_GROUP_ID": 16},
            {"MCC": "244", "MNC": "08", "MME_GROUP_ID": 17},
            {"MCC": "244", "MNC": "08", "MME_GROUP_ID": 18},
            {"MCC": "244", "MNC": "08", "MME_GROUP_ID": 19},
            {"MCC": "666", "MNC": "14", "MME_GROUP_ID": 12},
            {"MCC": "666", "MNC": "14", "MME_GROUP_ID": 13},
            {"MCC": "666", "MNC": "14", "MME_GROUP_ID": 14},
            {"MCC": "666", "MNC": "14", "MME_GROUP_ID": 15},
            {"MCC": "555", "MNC": "12", "MME_GROUP_ID": 16},
            {"MCC": "555", "MNC": "12", "MME_GROUP_ID": 17},
            {"MCC": "555", "MNC": "12", "MME_GROUP_ID": 18},
            {"MCC": "555", "MNC": "12", "MME_GROUP_ID": 19},
        ],
        init_enb_broadcast_plmns=[
            {"MCC": "244", "MNC": "08"},
            {"MCC": "666", "MNC": "14"},
            {"MCC": "555", "MNC": "12"},
            {"MCC": "244", "MNC": "09"},
            {"MCC": "666", "MNC": "15"},
            {"MCC": "555", "MNC": "13"},
        ],
        # X2AP setup configuration
        x2ap_setup_period=15,
        x2ap_setup_retries=3,
        x2ap_reset_period=15,
        x2ap_reset_retries=3,
        # X2AP scenario configuration
        enb_configuration_update_min=60,
        enb_configuration_update_max=300,
        x2_reset_min=300,
        x2_reset_max=360,
        # General params
        verbose=True,
        debug=False
    )

    ################################################################################
    # Start X2AP simulation connecting 128 X2 links to BTS
    ################################################################################
    print("Starting X2AP simulation...")
    emss1.xterm_start(x2ap=True)

    ################################################################################
    # Press the key to stop X2 simulation and delete dynamically created LNADJs
    ################################################################################
    k = ""
    while True:
        k = input("Enter 's' to start scenario or 'q' to stop...")
        if k == "s":
            ################################################################################
            # Press 's' to start sending X2 updates simulating ENBsims configuration changes
            ################################################################################
            print("Starting X2AP scenario...")
            emss1.xterm_start(scenario=True)
            break
        elif k == "q":
            break

    while k != "q":
        k = input("Enter 'q' to stop...")

    print("Stopping xterm")
    emss1.xterm_teardown()
    print("Deleting LNADJs")
    emss1.configure_delete("LNADJ")
